from typing import List

class Solution:
    def minStabilityFactor(self, nums: List[int], k: int) -> int:
        # A partition into at most k subarrays
        # Stability factor is max(max(sub) - min(sub))
        def check(limit: int) -> bool:
            parts = 1
            curr_min = nums[0]
            curr_max = nums[0]
            for x in nums[1:]:
                n_min = min(curr_min, x)
                n_max = max(curr_max, x)
                if n_max - n_min > limit:
                    parts += 1
                    curr_min = x
                    curr_max = x
                    if parts > k:
                        return False
                else:
                    curr_min = n_min
                    curr_max = n_max
            return parts <= k

        low = 0
        high = max(nums) - min(nums) if nums else 0
        ans = high

        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1

        return ans

#include <vector>
#include <algorithm>

class Solution {
public:
    int minStabilityFactor(std::vector<int>& nums, int k) {
        if (nums.empty()) return 0;
        int min_val = *std::min_element(nums.begin(), nums.end());
        int max_val = *std::max_element(nums.begin(), nums.end());

        auto check = [&](int limit) {
            int parts = 1;
            int curr_min = nums[0], curr_max = nums[0];
            for (size_t i = 1; i < nums.size(); ++i) {
                int n_min = std::min(curr_min, nums[i]);
                int n_max = std::max(curr_max, nums[i]);
                if (n_max - n_min > limit) {
                    parts++;
                    curr_min = nums[i];
                    curr_max = nums[i];
                    if (parts > k) return false;
                } else {
                    curr_min = n_min;
                    curr_max = n_max;
                }
            }
            return parts <= k;
        };

        int low = 0, high = max_val - min_val, ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        return ans;
    }
};

class Solution {
    public int minStabilityFactor(int[] nums, int k) {
        if (nums.length == 0) return 0;
        int minVal = Integer.MAX_VALUE, maxVal = Integer.MIN_VALUE;
        for (int x : nums) {
            minVal = Math.min(minVal, x);
            maxVal = Math.max(maxVal, x);
        }

        int low = 0, high = maxVal - minVal, ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(nums, k, mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private boolean check(int[] nums, int k, int limit) {
        int parts = 1;
        int currMin = nums[0], currMax = nums[0];
        for (int i = 1; i < nums.length; i++) {
            int nMin = Math.min(currMin, nums[i]);
            int nMax = Math.max(currMax, nums[i]);
            if (nMax - nMin > limit) {
                parts++;
                currMin = nums[i];
                currMax = nums[i];
                if (parts > k) return false;
            } else {
                currMin = nMin;
                currMax = nMax;
            }
        }
        return parts <= k;
    }
}

