var minStabilityFactor = function(nums, k) {
    if (nums.length === 0) return 0;
    let minVal = Infinity, maxVal = -Infinity;
    for (const x of nums) {
        if (x < minVal) minVal = x;
        if (x > maxVal) maxVal = x;
    }

    const check = (limit) => {
        let parts = 1;
        let currMin = nums[0], currMax = nums[0];
        for (let i = 1; i < nums.length; i++) {
            const nMin = Math.min(currMin, nums[i]);
            const nMax = Math.max(currMax, nums[i]);
            if (nMax - nMin > limit) {
                parts++;
                currMin = nums[i];
                currMax = nums[i];
                if (parts > k) return false;
            } else {
                currMin = nMin;
                currMax = nMax;
            }
        }
        return parts <= k;
    };

    let low = 0, high = maxVal - minVal, ans = high;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (check(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    return ans;
};
